{
  "headline": "Irinotecan hydrochloride is not on FDA's shortage list as of 2026-10-21; Ingenus Pharmaceuticals LLC discontinued its product with initial posting 2026-02-24",
  "headline_cites": ["D2", "E6"],
  "sentences": [
    {
      "text": "FDA's drug shortage list shows irinotecan hydrochloride is not listed as of 2026-10-21.",
      "cites": ["D2"]
    },
    {
      "text": "Ingenus Pharmaceuticals LLC posted a discontinuation for its irinotecan hydrochloride injection on 2026-02-24, citing a business decision to discontinue manufacture.",
      "cites": ["E6"]
    },
    {
      "text": "A label for Northstar Rx LLC (NDC 16714013101) names Gland Pharma Limited (FEI 3009056604) as a registered plant for analysis and manufacture, last inspected with NAI classification on 2023-07-28.",
      "cites": ["E5"]
    },
    {
      "text": "FDA inspection records for Gland Pharma Limited show three VAI classifications: inspection 848025 ending 2013-08-05, inspection 936901 ending 2015-06-30, and inspection 1110628 ending 2019-11-01.",
      "cites": ["E2", "E3", "E4"]
    },
    {
      "text": "Corvale General holds 64 vials of the 20 mg/mL, 5 mL presentation with 2.9 vials used per day, providing 22.3 days on hand.",
      "cites": ["D1"]
    },
    {
      "text": "The rule-ranked alternate manufacturers are Actavis Pharma, Inc., Apotex Corp., and BluePoint Laboratories; none are on FDA's shortage list today and their labels name no plant we could place.",
      "cites": ["D3", "D4", "D5"]
    },
    {
      "text": "Check current availability from the alternate manufacturers and verify label plant information before purchasing.",
      "cites": ["D3", "D4", "D5"]
    }
  ]
}
